-- Splynn Dimensional Market: the Kittani Hover Speed Pod and War Pod and the Kittani Patrol Flyer (printed 184-188).
-- 3 vehicle rows, with 22 locations and 13 weapon entries.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~364-splynn-hover-pods.sql
--
-- Written by scripts/vessel-sql.mjs from 1 worker file(s). Every value
-- is printable ASCII, every row cites its book, and a Main Body location
-- agrees with its vehicle's mdc_main_body.

INSERT OR IGNORE INTO vehicles (slug, name, system, vehicle_class, crew, passengers, speed_ground, speed_air, speed_water, dimensions, weight_tons, mdc_main_body, is_mega_damage, ar, cost, cost_note, description, source_book) VALUES
  ('kittani-hover-speed-pod', 'Kittani Hover Speed Pod (HVPC-099)', 'rifts', 'vehicle', 'One', NULL, 'Cannot drive on the ground; it hovers. Mach 1.5 (about 1050 mph/1680 km) up to 200 feet (61 m), often flown 2-4 feet (0.6-1.2 m) off the ground for show. Cruising speed 100-300 mph (160-480 km).', 'Limited flight up to 4,000 feet (1219 m); above 200 feet (61 m) it averages a 300 mph (480 km) cruise.', NULL, 'Height about 6 feet (1.8 m), width 8 feet (2.4 m), length 9 feet (2.7 m), stabilizer fins not counted. Versions for bulkier beings are built up to 50% larger.', NULL, 95, 1, NULL, 520000, '520,000 credits, most of it the power supply. Weapons and the custom racing and combat models raise it (see the description); an armed pod pays the weapon''s price plus 10,000 credits to mount it.', 'A one-man Kittani racer: a bubble of M.D.C. glass with one main engine at the rear and twelve small steering jets around the frame. Lightly armored but very hard to hit, it is flown for scouting, fast raids on soft targets and harassing Coalition Skycycles, and above all for street racing through city alleys and avenues. Only a rifle-class weapon or two fits in the frame under the nose. Custom racing models give +10% to piloting rolls in the pod and sell from 800,000 credits by maker; combat models add +1 dodge, +15 M.D.C. to the main body and +5% piloting for 220,000 credits more. A crashing pilot takes double the usual crash damage unless he gets clear, and the cockpit is not armored, so many wear jet packs. Micro-nuclear turbine, about two years'' life (often treated as disposable); solar supplies can be special ordered at little saving. No cargo beyond a rifle or two and what the pilot wears.', 'Rifts World Book 21: Splynn Dimensional Market p.184-185'),
  ('kittani-hover-war-pod', 'Kittani Hover War Pod (HV-MPC-216)', 'rifts', 'vehicle', 'Two: a pilot/gunner and a co-pilot/technical officer/gunner; one pilot can fly it alone. The one-man HV-MPC-113 seats one.', NULL, 'Cannot drive on the ground; it hovers. Mach 2 (about 1400 mph/2240 km) up to 200 feet (61 m). Cruising speed 200-500 mph (320-804 km).', 'Limited flight up to 6,000 feet (1828 m); above 200 feet (61 m) it averages a 300 mph (480 km) cruise.', NULL, 'Height about 10 feet (3 m), width about 8 feet (2.4 m), length 12 feet (3.7 m), stabilizer fins not counted. Versions for bulkier beings are built up to 50% larger.', NULL, 100, 1, NULL, 4200000, '4.2 million credits fully armed and loaded; the particle beam gun alone is one million.', 'The armed, armored military cousin of the Speed Pod: the same glass bubble with a bigger engine and twelve steering jets, built to take and deal real damage while staying hard to hit. Still far lighter than power armor, it serves as scout, fast attack and patrol craft against soft targets, escort, and city pacification unit, and a good pilot can harry Coalition Skycycles in it. The pilot flies and works the under-gun; the co-pilot runs communications and sensors and fires the particle beams on top. The one-man HV-MPC-113 gives up the upper co-pilot compartment for a 12-shot mini-missile launcher, the one heavy addition to standard light weaponry. Neither cockpit is reinforced, and a crashing pilot takes double the usual crash damage unless he gets clear. Micro-nuclear turbine, about five years'' life (often treated as disposable); solar supplies can be special ordered at little saving. No cargo beyond a rifle or two and what the crew wear.', 'Rifts World Book 21: Splynn Dimensional Market p.185-187'),
  ('kittani-patrol-flyer', 'Kittani Patrol Flyer (K-PF 20)', 'rifts', 'vehicle', 'One; usually a Kittani or another human-sized pilot. The Sunaj are fond of it.', NULL, 'Cannot drive on the ground; hovers over land or water, from a crawl of inches an hour upward. VTOL.', 'Mach 2 (about 1400 mph/2240 km) maximum, ceiling 30,000 feet (9144 m); average cruising speed 40-100 mph (64-160 km).', 'None underwater.', 'Height 12 feet (3.7 m). Width 20 feet (6.1 m) with the wings spread, 10 feet (3 m) with them folded for VTOL. Length 24 feet (7.3 m).', NULL, 220, 1, NULL, 8000000, '8 million credits fully armed and loaded; a 20-year power system costs 1.2 million more.', 'A small, sleek one-man Kittani jet that can take off vertically, hover and fly, used mainly to patrol the coasts and skies of Atlantis. It is quick and light and stays low enough to pass beneath radar. Wing lasers, a swiveling laser arm under the belly and a modular missile launcher arm it, and it carries the full sensor suite of an advanced war vehicle. Every Kittani can fly it. The cockpit is not reinforced. Micro-nuclear turbine, about five years'' life (often treated as disposable). No cargo beyond a rifle or two and what the pilot wears.', 'Rifts World Book 21: Splynn Dimensional Market p.187-188');

INSERT OR IGNORE INTO vehicle_locations (vehicle_slug, location, mdc, mdc_note, ordinal) VALUES
  ('kittani-hover-speed-pod', 'Stabilizer Fins', 15, 'Each.', 1),
  ('kittani-hover-speed-pod', 'Main Body', 95, 'Printed as Main Body/Cockpit. Depleting it destroys the pod; there is no reinforced compartment, so the pilot relies on his own armor.', 2),
  ('kittani-hover-speed-pod', 'Main Thruster', 30, 'Called shot only, -3 to strike. Destroying it crashes the pod.', 3),
  ('kittani-hover-speed-pod', 'Maneuvering Thrusters (12)', 5, 'Each. Called shot only, -6 to strike. Three lost cancel the pod''s bonuses, six turn them into penalties, eight crash it.', 4),
  ('kittani-hover-speed-pod', 'Undercarriage Weapon', 30, 'Only when a weapon is fitted. Called shot only.', 5),
  ('kittani-hover-war-pod', 'Main Body', 100, 'Depleting it destroys the pod.', 1),
  ('kittani-hover-war-pod', 'Cockpits (2)', 75, 'Each. Separate from the main body and not reinforced: once either the cockpit or the main body is breached, the crew relies on its own armor.', 2),
  ('kittani-hover-war-pod', 'Main Thruster', 50, 'Called shot only, -3 to strike. Destroying it crashes the pod.', 3),
  ('kittani-hover-war-pod', 'Maneuvering Thrusters (12)', 5, 'Each. Called shot only, -6 to strike. Three lost cancel the pod''s bonuses, six turn them into penalties, eight crash it.', 4),
  ('kittani-hover-war-pod', 'Stabilizer Fins', 15, 'Each. Called shot only.', 5),
  ('kittani-hover-war-pod', 'Under-Gun Laser', 30, NULL, 6),
  ('kittani-hover-war-pod', 'Top Mount Particle Beam', 50, NULL, 7),
  ('kittani-hover-war-pod', 'Missile Launcher', 50, 'The one-man HV-MPC-113 only.', 8),
  ('kittani-patrol-flyer', 'Main Body', 220, 'Depleting it destroys the craft.', 1),
  ('kittani-patrol-flyer', 'Cockpit', 75, 'Not reinforced: once the cockpit or the main body is breached, the pilot relies on his own armor.', 2),
  ('kittani-patrol-flyer', 'Main Thruster', 100, 'Called shot only, -3 to strike.', 3),
  ('kittani-patrol-flyer', 'Maneuvering Thrusters (3)', 35, 'Each. Called shot only, -3 to strike.', 4),
  ('kittani-patrol-flyer', 'Wings (4)', 100, 'Each. One lost: speed and altitude -10%, -10% piloting. Two lost: speed -30%, no bonuses, -25% piloting (doubled on trick maneuvers). Three or four lost: speed -50%, -50% piloting; it should land before it crashes.', 5),
  ('kittani-patrol-flyer', 'Wing Guns (2)', 10, 'Each; small.', 6),
  ('kittani-patrol-flyer', 'Underbelly Laser Arm', 35, 'Called shot only, -3 to strike.', 7),
  ('kittani-patrol-flyer', 'Missile Launcher', 100, 'Above and behind the left wing.', 8),
  ('kittani-patrol-flyer', 'Top Mounted Sensor Cluster', 70, 'Called shot only, -3 to strike.', 9);

INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('kittani-hover-speed-pod', 1, 'Special Bonuses', NULL, 0, NULL, NULL, NULL, '+3 automatic dodge at cruising speed or slower; +7 dodge above cruising speed', 'Above cruising speed it can also dodge automatically, with no bonus. Stunt and maneuver penalties are halved at or below cruising speed, but only for a pilot with Pilot: Hover Pod.'),
  ('kittani-hover-speed-pod', 2, 'Hand to Hand Combat', 'Sideswipe 1D6 M.D. per 100 mph (160 km); stabilizer fin sideswipe 1D4 M.D. per 100 mph', 1, 'Hand to hand', NULL, NULL, NULL, 'Otherwise not applicable. In a sideswipe the pod itself takes half the damage it deals, likely wrecking it; a fin sideswipe tears the fin away and does 1D6 M.D. to the main body.'),
  ('kittani-hover-speed-pod', 3, 'Optional Twin Nose Lasers', '4D6 M.D. per twin blast, 2D6 M.D. per single shot', 1, '2000 feet (610 m)', 'Equal to the pilot''s combined attacks', '30 twin blasts or 60 single shots from a separate E-Clip; effectively unlimited if wired to the nuclear plant, which cuts the plant''s life to a year and a half', NULL, 'The commonest pod armament, a heavy double laser. Anti-vehicle (other pods) first, anti-personnel second. Swapping the E-Clip takes someone outside the pod one melee round.'),
  ('kittani-hover-war-pod', 1, 'Under-Gun Laser', '6D6 M.D. per simultaneous twin blast, or 3D6 M.D. per single blast', 1, '2000 feet (610 m)', 'Equal to the pilot''s hand to hand attacks', '100 twin blasts per hour', NULL, 'A small twin-barreled laser below the pilot''s cockpit, fired by the pilot. Anti-personnel first, defense second.'),
  ('kittani-hover-war-pod', 2, 'Top Mounted Particle Beams', '2D4x10+8 M.D. per twin blast, 1D4x10+4 M.D. per single blast', 1, '2,000 feet (610 m)', 'Equal to the pilot''s hand to hand attacks', '60 twin blasts per hour; regenerates', NULL, 'A pair on the pod''s top, both firing at one target; the co-pilot''s weapon. Anti-aircraft first, anti-vehicle second. One million credits of the price.'),
  ('kittani-hover-war-pod', 3, 'Optional Mini-Missile Launcher (One-Man Only)', '1D4x10 M.D. per armor-piercing mini-missile; other types vary', 1, 'One mile (1.6 km)', 'Singly or in volleys of 2, 4, 6, 8 or all 12', '12 armor-piercing mini-missiles', NULL, 'Fitted only to the one-man HV-MPC-113, where it takes the place of the co-pilot''s compartment on top. Anti-armor first, anti-aircraft second.'),
  ('kittani-hover-war-pod', 4, 'Hand to Hand Combat', 'Sideswipe 1D6 M.D. per 100 mph (160 km); stabilizer fin sideswipe 1D4 M.D. per 100 mph', 1, 'Hand to hand', NULL, NULL, NULL, 'Otherwise not applicable. In a sideswipe the pod itself takes half the damage it deals, likely wrecking it; a fin sideswipe tears the fin away and does 1D6 M.D. to the main body.'),
  ('kittani-hover-war-pod', 5, 'Special Bonuses', NULL, 0, NULL, NULL, NULL, '+2 automatic dodge at cruising speed or slower; +5 dodge above cruising speed', 'Above cruising speed it can also dodge automatically, with no bonus. Stunt and maneuver penalties fall by 20% at or below cruising speed, but only for a pilot with Pilot: Hover Pod, which every Kittani has.'),
  ('kittani-patrol-flyer', 1, 'Wing Guns (2)', '4D6 M.D. per simultaneous twin blast, or 2D6 M.D. per single blast', 1, '2000 feet (610 m)', 'Equal to the pilot''s hand to hand attacks', 'Effectively unlimited', NULL, 'A small light laser in each wing. Anti-personnel first, defense second.'),
  ('kittani-patrol-flyer', 2, 'Underbelly Laser Arm', '3D6 M.D. per single blast', 1, '2,000 feet (610 m)', 'Equal to the pilot''s hand to hand attacks', 'Effectively unlimited', NULL, 'Extends up to 12 feet (3.7 m) and turns full circle, covering a 180-degree downward arc from nose to tail. Anti-personnel first, defense second.'),
  ('kittani-patrol-flyer', 3, 'Modular Missile Launcher', 'By missile type', 1, 'By missile type', 'One at a time or in volleys of two', '24 mini-missiles, four short-range missiles or two medium-range missiles', NULL, 'An interchangeable module taking mini-, short- or medium-range missiles. Anti-armor first, anti-aircraft second.'),
  ('kittani-patrol-flyer', 4, 'Hand to Hand Combat', 'Wing sideswipe 1D6 M.D. per 100 mph (160 km); a strike or ram with the laser arm 1 M.D.', 1, 'Hand to hand', NULL, NULL, NULL, 'Otherwise not applicable. A wing sideswipe does a quarter of its damage to the wing; the laser-arm strike is -3 to strike.'),
  ('kittani-patrol-flyer', 5, 'Special Bonuses', NULL, 0, NULL, NULL, NULL, '+2 dodge at cruising speed or slower; +4 dodge above cruising speed; +1 strike with energy weapons; +3 strike with missiles', 'Carries the full sensor suite standard for advanced war vehicles.');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 3 machines are in' AS assertion, count(*) AS got, 3 AS want
  FROM vehicles WHERE slug IN ('kittani-hover-speed-pod', 'kittani-hover-war-pod', 'kittani-patrol-flyer');
SELECT 'their 22 locations are in' AS assertion, count(*) AS got, 22 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('kittani-hover-speed-pod', 'kittani-hover-war-pod', 'kittani-patrol-flyer');
SELECT 'their 13 weapon entries are in' AS assertion, count(*) AS got, 13 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('kittani-hover-speed-pod', 'kittani-hover-war-pod', 'kittani-patrol-flyer');
SELECT 'each main body location equals mdc_main_body' AS assertion, count(*) AS got, 0 AS want
  FROM vehicles v JOIN vehicle_locations l ON l.vehicle_slug = v.slug AND l.location = 'Main Body'
  WHERE v.slug IN ('kittani-hover-speed-pod', 'kittani-hover-war-pod', 'kittani-patrol-flyer') AND l.mdc IS NOT NULL AND v.mdc_main_body IS NOT NULL AND l.mdc <> v.mdc_main_body;

